package com.vandorlabs.neoforge.propulsion;
import com.google.gson.*;
import com.vandorlabs.propulsion.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Actual native conversion replay against released Source transactions, not a scalar-only surrogate. */
@EventBusSubscriber(modid="vandorlabs")
public final class PropulsionShapeChecks {
 private static final java.util.Map<String,NativePropulsionBlock> BLOCKS=new java.util.LinkedHashMap<>();private static BlockEntityType<NativePropulsionEntity> TYPE;private static int checks,profiles;private static final BlockPos BASE=new BlockPos(7768,90,7768),SAVE=BASE.south(8);
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("propulsion-shape-");}private static void need(boolean yes,String message){checks++;if(!yes)throw new AssertionError("Propulsion shape "+message+" profile="+profiles);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration{@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{for(var d:PropulsionDefinition.values()){var block=new NativePropulsionBlock(d.id,BlockBehaviour.Properties.of().strength(5,10),()->TYPE,BLOCKS::get);BLOCKS.put(d.id,block);h.register(ResourceLocation.parse("vandorlabs:propulsion_shape_fixture_"+d.id),block);}});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.of((p,s)->new NativePropulsionEntity(TYPE,p,s),BLOCKS.values().toArray(NativePropulsionBlock[]::new)).build(null);h.register(ResourceLocation.parse("vandorlabs:propulsion_shape_fixture"),TYPE);});}}
 private static BlockPos cell(Direction face,int size,int index){int right=PropulsionEmission.right(face.get3DDataValue()),up=PropulsionEmission.up(face.get3DDataValue()),x=size==1?0:index/size,y=size==1?0:index%size;return BASE.offset(PropulsionEmission.dx(right)*x+PropulsionEmission.dx(up)*y,PropulsionEmission.dy(right)*x+PropulsionEmission.dy(up)*y,PropulsionEmission.dz(right)*x+PropulsionEmission.dz(up)*y);}
 private static void write(ServerLevel w)throws Exception{w.getChunkAt(BASE);try(var lines=java.nio.file.Files.lines(java.nio.file.Path.of(System.getProperty("vandorlabs.propulsionShapeReference")))){for(String line:(Iterable<String>)lines::iterator){var r=JsonParser.parseString(line).getAsJsonObject();String id=r.get("block").getAsString();var block=BLOCKS.get(id);var face=Direction.from3DDataValue(r.get("face").getAsInt());var before=r.getAsJsonArray("before");var after=r.getAsJsonArray("after");int size=before.size()==1?1:2;var owners=new java.util.ArrayList<NativePropulsionEntity>();
  for(int i=0;i<before.size();i++){var pos=cell(face,size,i);w.setBlock(pos,Blocks.AIR.defaultBlockState(),18);var s=before.get(i).getAsJsonObject();w.setBlock(pos,block.defaultBlockState().setValue(NativePropulsionBlock.FACING,face).setValue(NativePropulsionBlock.POWERED,s.get("powered").getAsBoolean()),18);var owner=(NativePropulsionEntity)w.getBlockEntity(pos);owner.loadWithComponents(TagParser.parseTag(s.get("saved").getAsString()),w.registryAccess());owners.add(owner);}
  int fault=r.get("fault").getAsInt();var fail=cell(face,size,before.size()-1);var writer=new NativePropulsionShape.Writer(){public boolean write(ServerLevel world,BlockPos pos,BlockState state){return world.setBlock(pos,state,18);}public void phase(String phase,BlockPos pos){if(fault!=0&&pos.equals(fail)&&phase.equals(fault==1?"before-write":"after-write"))throw new IllegalStateException("actual Source stage injection");}};
  boolean result=NativePropulsionShape.configure(owners.getLast(),r.get("shape").getAsInt(),null,writer);need(result==r.get("result").getAsBoolean(),"Source return "+id+" face="+face+" target="+r.get("shape")+" fault="+fault);
  for(int i=0;i<after.size();i++){var pos=cell(face,size,i);var expected=after.get(i).getAsJsonObject();var owner=(NativePropulsionEntity)w.getBlockEntity(pos);need(owner==owners.get(i)&&!owner.inert(),"Source same physical owner");need(w.getBlockState(pos).getBlock()==BLOCKS.get(expected.get("block").getAsString())&&w.getBlockState(pos).getValue(NativePropulsionBlock.FACING).get3DDataValue()==expected.get("face").getAsInt()&&w.getBlockState(pos).getValue(NativePropulsionBlock.POWERED)==expected.get("powered").getAsBoolean(),"Source target block/facing/power");need(owner.settings().equals(NativeRedstoneLightSettings.read(TagParser.parseTag(expected.get("saved").getAsString()))),"Source every member settings");}
  for(int i=0;i<before.size();i++)w.setBlock(cell(face,size,i),Blocks.AIR.defaultBlockState(),18);profiles++;
 }}need(profiles==2430,"Source coverage");w.setBlock(SAVE,BLOCKS.get("rocket_thruster").defaultBlockState(),18);var saved=(NativePropulsionEntity)w.getBlockEntity(SAVE);var tag=new CompoundTag();tag.putBoolean("ManualOn",true);tag.putBoolean("LightInitialized",true);tag.putInt("ParticleLevel",3);tag.putInt("PropulsionSideTexture",64);tag.putString("FutureEngineChoice","opaque:shape");saved.loadWithComponents(tag,w.registryAccess());need(NativePropulsionShape.configure(saved,1,null)&&w.getBlockEntity(SAVE)==saved,"saved converted owner same identity");var recoveryPos=SAVE.east(3);w.setBlock(recoveryPos,BLOCKS.get("rocket_thruster").defaultBlockState(),18);var recovery=(NativePropulsionEntity)w.getBlockEntity(recoveryPos);recovery.loadWithComponents(tag,w.registryAccess());var old=recovery.saveWithoutMetadata(w.registryAccess());boolean failed=false;try{NativePropulsionShape.configure(recovery,1,null,new NativePropulsionShape.Writer(){boolean wrote;public boolean write(ServerLevel world,BlockPos pos,BlockState state){if(wrote)return false;wrote=true;return world.setBlock(pos,state,18);}public void phase(String phase,BlockPos pos){if(phase.equals("after-write"))throw new IllegalStateException("injected failed rollback");}});}catch(IllegalStateException expected){failed=true;}need(failed&&w.getBlockEntity(recoveryPos)==recovery&&recovery.inert(),"refused rollback retains original physical owner inert");var retained=recovery.saveWithoutMetadata(w.registryAccess());need(retained.contains("PropulsionShapeRecovery")&&retained.getString("FutureEngineChoice").equals(old.getString("FutureEngineChoice"))&&retained.getInt("ParticleLevel")==old.getInt("ParticleLevel"),"shape recovery retains original opaque and selected choices");w.setChunkForced(SAVE.getX()>>4,SAVE.getZ()>>4,true);}
 private static void read(ServerLevel w){w.getChunkAt(SAVE);var saved=(NativePropulsionEntity)w.getBlockEntity(SAVE);need(saved!=null&&!saved.inert()&&saved.getBlockState().getBlock()==BLOCKS.get("rocket_thruster_hexagonal")&&saved.settings().data().sideTexture==64&&saved.settings().data().particleLevel==3,"converted block and settings survive restart");need(saved.saveWithoutMetadata(w.registryAccess()).getString("FutureEngineChoice").equals("opaque:shape"),"opaque saved owner remains");var recovery=(NativePropulsionEntity)w.getBlockEntity(SAVE.east(3));need(recovery!=null&&recovery.inert()&&recovery.saveWithoutMetadata(w.registryAccess()).contains("PropulsionShapeRecovery")&&recovery.saveWithoutMetadata(w.registryAccess()).getString("FutureEngineChoice").equals("opaque:shape"),"refused shape rollback remains inert and owned after restart");}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;try{var w=e.getServer().overworld();if(phase().endsWith("write"))write(w);else read(w);e.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][propulsion-shape] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks+" actualSourceProfiles="+profiles);}catch(Throwable failure){System.err.println("[vandorlabs][propulsion-shape] FAIL "+failure);failure.printStackTrace();}finally{e.getServer().halt(false);}}
}
